-- ===========================================================================
-- 140_discovery_leads.sql
-- ===========================================================================
-- Additive seller discovery reads over the reviewed marketplace foundation.
--
-- Scope: server-authorized filters and sorts, real cursor pagination, radius
-- discovery with approximate location only, and explainable matching inputs.
-- The seller lead projection never carries the buyer's exact address,
-- coordinates, contacts or another seller's offers.
--
-- Named prerequisites (applied in this order before this package):
--   marketplace/020 foundation, 021 request coordinates, 023 multi-negotiation
--   (discovery closes at the first-acceptance window). 023 is required because
--   the approved rule closes discovery at acceptance expiry while accepted
--   meetings survive; this file reads `acceptance_expires_at` directly.
--
-- Location policy: the seller's own declared discovery origin (approximate
-- area label plus optional coordinates and a service radius) is stored on the
-- seller's account. Distance is computed only when both the request and the
-- seller origin carry coordinates; otherwise the manual area-label fallback is
-- used and no distance is fabricated. US locations are preferred in ordering
-- without excluding other countries.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

DO $guard$ BEGIN
  IF to_regclass('hocalist.requests') IS NULL
     OR to_regclass('hocalist.memberships') IS NULL
     OR to_regprocedure('hocalist.marketplace_assert_role(uuid,text)') IS NULL
     OR to_regclass('hocalist.marketplace_receipts') IS NULL THEN
    RAISE EXCEPTION 'marketplace 020 prerequisite missing';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='hocalist' AND table_name='requests' AND column_name='acceptance_expires_at'
  ) THEN
    RAISE EXCEPTION 'marketplace multi-negotiation 023 prerequisite missing';
  END IF;
  IF to_regclass('hocalist.seller_discovery_origins') IS NOT NULL
     OR to_regprocedure('hocalist.marketplace_discovery_leads(text,uuid,text,integer,text,text,integer,text,bigint,bigint)') IS NOT NULL THEN
    RAISE EXCEPTION 'discovery leads already installed';
  END IF;
END; $guard$;

-- ---------------------------------------------------------------------------
-- Seller discovery origin (owner-scoped, approximate)
-- ---------------------------------------------------------------------------

CREATE TABLE hocalist.seller_discovery_origins (
  seller_user_id uuid PRIMARY KEY REFERENCES hocalist.profiles(id),
  seller_profile_id uuid NOT NULL REFERENCES hocalist.memberships(id),
  area_label text CHECK (area_label IS NULL OR length(btrim(area_label)) BETWEEN 1 AND 150),
  latitude double precision,
  longitude double precision,
  radius_miles integer NOT NULL DEFAULT 25 CHECK (radius_miles BETWEEN 1 AND 500),
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT discovery_origin_coordinates_pair CHECK (
    (latitude IS NULL AND longitude IS NULL)
    OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)
  )
);
ALTER TABLE hocalist.seller_discovery_origins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hocalist.seller_discovery_origins FROM PUBLIC, anon, authenticated, service_role;

-- Great-circle distance in statute miles. Immutable and side-effect free.
CREATE FUNCTION hocalist.discovery_distance_miles(
  p_lat1 double precision, p_lng1 double precision,
  p_lat2 double precision, p_lng2 double precision
) RETURNS double precision
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
  SELECT 3958.7613 * 2 * asin(least(1.0, sqrt(
    power(sin(radians(p_lat2 - p_lat1) / 2), 2) +
    cos(radians(p_lat1)) * cos(radians(p_lat2)) *
      power(sin(radians(p_lng2 - p_lng1) / 2), 2)
  )));
$$;
REVOKE ALL ON FUNCTION hocalist.discovery_distance_miles(double precision,double precision,double precision,double precision)
  FROM PUBLIC, anon, authenticated, service_role;

-- Declared matching inputs for one seller: active and approved Store listing
-- category ids. Declared categories are server reads; the client never sends
-- its own matching terms.
CREATE FUNCTION hocalist.discovery_declared_category_ids(p_seller uuid)
RETURNS uuid[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT coalesce(array_agg(DISTINCT l.category_id), ARRAY[]::uuid[])
  FROM hocalist.store_listings l
  WHERE l.seller_user_id = p_seller
    AND l.status = 'active'
    AND l.moderation_status = 'approved'
    AND l.category_id IS NOT NULL;
$$;

-- Shared authorization for the signed-in reads in this package: the caller
-- must be authenticated, must not hold any restricted/disabled membership and
-- must hold at least one active membership. Role-specific RPCs use
-- marketplace_assert_role instead; this helper is for both-role projections.
CREATE FUNCTION hocalist.discovery_assert_active_member(p_user uuid)
RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF p_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = p_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM hocalist.memberships
                 WHERE user_id = p_user AND status = 'active') THEN
    RAISE EXCEPTION 'active_membership_required' USING ERRCODE='42501';
  END IF;
END $$;

CREATE FUNCTION hocalist.discovery_origin_json()
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  o hocalist.seller_discovery_origins%ROWTYPE;
BEGIN
  PERFORM hocalist.marketplace_assert_role(u, 'seller');
  SELECT * INTO o FROM hocalist.seller_discovery_origins WHERE seller_user_id = u;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('configured', false);
  END IF;
  RETURN jsonb_build_object(
    'configured', true,
    'area_label', o.area_label,
    'coordinates_present', o.latitude IS NOT NULL,
    'radius_miles', o.radius_miles,
    'revision', o.revision);
END $$;

-- Sets or replaces the signed-in seller's discovery origin. Coordinates are
-- optional and only ever their own; the client cannot set another seller's
-- origin because the identity comes from auth.uid().
CREATE FUNCTION hocalist.discovery_origin_set(p_key text, p_input jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  m uuid;
  h text;
  receipt hocalist.marketplace_receipts%ROWTYPE;
  v_area text;
  v_lat double precision;
  v_lng double precision;
  v_radius integer;
  v_revision bigint;
BEGIN
  m := hocalist.marketplace_assert_role(u, 'seller');
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 128
     OR p_input IS NULL OR jsonb_typeof(p_input) <> 'object'
     OR p_input - ARRAY['area_label','latitude','longitude','radius_miles'] <> '{}'::jsonb THEN
    RAISE EXCEPTION 'invalid_origin' USING ERRCODE='22023';
  END IF;
  v_area := nullif(btrim(coalesce(p_input->>'area_label','')), '');
  IF v_area IS NOT NULL AND length(v_area) > 150 THEN
    RAISE EXCEPTION 'invalid_field: area_label' USING ERRCODE='22023';
  END IF;
  IF (p_input->>'latitude' IS NULL) <> (p_input->>'longitude' IS NULL) THEN
    RAISE EXCEPTION 'invalid_field: coordinates' USING ERRCODE='22023';
  END IF;
  IF p_input->>'latitude' IS NOT NULL THEN
    IF jsonb_typeof(p_input->'latitude') <> 'number'
       OR jsonb_typeof(p_input->'longitude') <> 'number' THEN
      RAISE EXCEPTION 'invalid_field: coordinates' USING ERRCODE='22023';
    END IF;
    v_lat := (p_input->>'latitude')::double precision;
    v_lng := (p_input->>'longitude')::double precision;
    IF v_lat NOT BETWEEN -90 AND 90 OR v_lng NOT BETWEEN -180 AND 180 THEN
      RAISE EXCEPTION 'invalid_field: coordinates' USING ERRCODE='22023';
    END IF;
  END IF;
  v_radius := 25;
  IF p_input ? 'radius_miles' AND jsonb_typeof(p_input->'radius_miles') <> 'null' THEN
    IF jsonb_typeof(p_input->'radius_miles') <> 'number'
       OR (p_input->>'radius_miles') !~ '^[0-9]{1,3}$' THEN
      RAISE EXCEPTION 'invalid_field: radius_miles' USING ERRCODE='22023';
    END IF;
    v_radius := (p_input->>'radius_miles')::integer;
    IF v_radius NOT BETWEEN 1 AND 500 THEN
      RAISE EXCEPTION 'invalid_field: radius_miles' USING ERRCODE='22023';
    END IF;
  END IF;
  h := encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(u::text||':discovery_origin:'||p_key,0));
  SELECT * INTO receipt FROM hocalist.marketplace_receipts
    WHERE user_id = u AND operation = 'discovery.origin_set' AND idempotency_key = p_key;
  IF FOUND THEN
    IF receipt.request_hash <> h THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001'; END IF;
    RETURN receipt.result;
  END IF;
  INSERT INTO hocalist.seller_discovery_origins(
    seller_user_id, seller_profile_id, area_label, latitude, longitude, radius_miles)
  VALUES (u, m, v_area, v_lat, v_lng, v_radius)
  ON CONFLICT (seller_user_id) DO UPDATE SET
    seller_profile_id = excluded.seller_profile_id,
    area_label = excluded.area_label,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    radius_miles = excluded.radius_miles,
    revision = hocalist.seller_discovery_origins.revision + 1,
    updated_at = now()
  RETURNING revision INTO v_revision;
  INSERT INTO hocalist.marketplace_receipts(user_id, operation, idempotency_key, request_hash, result)
  VALUES (u, 'discovery.origin_set', p_key, h, jsonb_build_object(
    'configured', true,
    'area_label', v_area,
    'coordinates_present', v_lat IS NOT NULL,
    'radius_miles', v_radius,
    'revision', v_revision));
  RETURN jsonb_build_object(
    'configured', true, 'area_label', v_area,
    'coordinates_present', v_lat IS NOT NULL,
    'radius_miles', v_radius, 'revision', v_revision);
END $$;

-- ---------------------------------------------------------------------------
-- Seller-safe lead projection with match and approximate distance
-- ---------------------------------------------------------------------------

-- Builds one seller-visible request projection. Distinct from
-- marketplace_lead_json so this package stays readable even when later
-- migrations change the buyer/owner serializer. It never selects latitude,
-- longitude, address lines, postal code or country-agnostic contacts.
CREATE FUNCTION hocalist.discovery_lead_json(
  p_request uuid,
  p_distance_miles double precision DEFAULT NULL,
  p_match integer DEFAULT NULL,
  p_match_reasons jsonb DEFAULT '[]'::jsonb
) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT jsonb_build_object(
    'request_id', r.id,
    'kind', r.kind,
    'title', r.title,
    'description', r.description,
    'condition', r.condition,
    'service_type', r.service_type,
    'quantity', r.quantity,
    'budget', jsonb_build_object(
      'minimum_minor', r.budget_min_minor,
      'maximum_minor', r.budget_max_minor,
      'currency', r.currency_code),
    'accepts_higher_offers', r.accepts_higher_offers,
    'category_id', r.category_id,
    'buyer_profile_id', r.buyer_profile_id,
    'buyer_display_name', coalesce(nullif(btrim(rp.display_name), ''), 'Hocalist member'),
    'area_label', coalesce(rp.area_label, r.city, r.region),
    'request_revision', r.revision,
    'acceptance_expires_at', r.acceptance_expires_at,
    'discovery_open', r.status = 'active'
      AND (r.acceptance_expires_at IS NULL OR now() < r.acceptance_expires_at),
    'published_at', r.created_at,
    'distance_miles', p_distance_miles,
    'match_percent', p_match,
    'match_reasons', coalesce(p_match_reasons, '[]'::jsonb),
    'verified_purchase_count', (
      SELECT count(*)::integer FROM hocalist.sale_confirmations s
      WHERE s.buyer_user_id = r.buyer_user_id)
  )
  FROM hocalist.requests r
  LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = r.buyer_profile_id
  WHERE r.id = p_request;
$$;

-- Server-authorized seller discovery. Filters, sorts, radius and cursor are
-- all applied server-side; the returned projection is the only lead shape a
-- seller can read. `p_cursor` encodes the active sort so a cursor from another
-- sort is rejected instead of silently returning wrong rows.
--
-- Sorts: newest | recommended | closest | budget.
-- recommended: explainable match (declared category 50, area overlap 30,
--   in-radius 20), then US priority, then recency. Requests with no
--   explainable match sort last and report a null match_percent.
-- closest: ascending distance when available; requests without coordinates
--   sort last and never carry a fabricated distance.
-- budget: highest maximum budget first; unknown budgets sort last.
CREATE FUNCTION hocalist.marketplace_discovery_leads(
  p_kind text DEFAULT NULL,
  p_category uuid DEFAULT NULL,
  p_area text DEFAULT NULL,
  p_limit integer DEFAULT 50,
  p_cursor text DEFAULT NULL,
  p_sort text DEFAULT 'newest',
  p_radius_miles integer DEFAULT NULL,
  p_query text DEFAULT NULL,
  p_budget_min_minor bigint DEFAULT NULL,
  p_budget_max_minor bigint DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_size integer;
  v_sort text := coalesce(nullif(btrim(p_sort), ''), 'newest');
  v_origin hocalist.seller_discovery_origins%ROWTYPE;
  v_radius integer;
  v_declared uuid[];
  v_seller_area text;
  v_query text;
  v_cursor_sort text;
  v_cursor_metric double precision;
  v_cursor_match integer;
  v_cursor_us integer;
  v_cursor_micros bigint;
  v_cursor_id uuid;
  v_rows jsonb;
  v_next text;
  v_last_metric double precision;
  v_last_match integer;
  v_last_us integer;
  v_last_micros bigint;
  v_last_id uuid;
  v_has_more boolean;
BEGIN
  PERFORM hocalist.marketplace_assert_role(v_user, 'seller');
  IF p_kind IS NOT NULL AND p_kind NOT IN ('product','service') THEN
    RAISE EXCEPTION 'invalid_field: kind' USING ERRCODE='22023';
  END IF;
  IF p_area IS NOT NULL AND length(btrim(p_area)) NOT BETWEEN 1 AND 150 THEN
    RAISE EXCEPTION 'invalid_field: area' USING ERRCODE='22023';
  END IF;
  v_query := nullif(btrim(coalesce(p_query,'')), '');
  IF v_query IS NOT NULL AND length(v_query) > 160 THEN
    RAISE EXCEPTION 'invalid_field: query' USING ERRCODE='22023';
  END IF;
  IF p_radius_miles IS NOT NULL AND p_radius_miles NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'invalid_field: radius' USING ERRCODE='22023';
  END IF;
  IF v_sort NOT IN ('newest','recommended','closest','budget') THEN
    RAISE EXCEPTION 'invalid_field: sort' USING ERRCODE='22023';
  END IF;
  v_size := greatest(1, least(coalesce(p_limit, 50), 100));

  SELECT * INTO v_origin FROM hocalist.seller_discovery_origins WHERE seller_user_id = v_user;
  IF NOT FOUND THEN
    v_origin.radius_miles := NULL;
  END IF;
  v_radius := coalesce(p_radius_miles, v_origin.radius_miles);
  SELECT coalesce(rp.area_label, '') INTO v_seller_area
    FROM hocalist.memberships m
    LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = m.id
    WHERE m.user_id = v_user AND m.role = 'seller' AND m.status = 'active'
    LIMIT 1;
  v_seller_area := coalesce(v_seller_area, '');
  v_declared := hocalist.discovery_declared_category_ids(v_user);

  IF p_cursor IS NOT NULL THEN
    BEGIN
      v_cursor_sort := split_part(p_cursor, '|', 1);
      IF v_cursor_sort <> v_sort THEN
        RAISE EXCEPTION 'invalid_cursor' USING ERRCODE='22023';
      END IF;
      IF v_sort = 'recommended' THEN
        v_cursor_match := split_part(p_cursor, '|', 2)::integer;
        v_cursor_us := split_part(p_cursor, '|', 3)::integer;
        v_cursor_micros := split_part(p_cursor, '|', 4)::bigint;
        v_cursor_id := split_part(p_cursor, '|', 5)::uuid;
      ELSIF v_sort = 'closest' THEN
        v_cursor_metric := split_part(p_cursor, '|', 2)::double precision;
        v_cursor_micros := split_part(p_cursor, '|', 3)::bigint;
        v_cursor_id := split_part(p_cursor, '|', 4)::uuid;
      ELSIF v_sort = 'budget' THEN
        v_cursor_metric := split_part(p_cursor, '|', 2)::double precision;
        v_cursor_micros := split_part(p_cursor, '|', 3)::bigint;
        v_cursor_id := split_part(p_cursor, '|', 4)::uuid;
      ELSE
        v_cursor_micros := split_part(p_cursor, '|', 2)::bigint;
        v_cursor_id := split_part(p_cursor, '|', 3)::uuid;
      END IF;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_cursor' USING ERRCODE='22023';
    END;
  END IF;

  SELECT coalesce(jsonb_agg(row_json ORDER BY
      row_match DESC, row_us DESC, row_micros DESC, row_id DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      r.id AS row_id,
      (extract(epoch FROM r.created_at) * 1000000)::bigint AS row_micros,
      CASE WHEN r.country_code = 'US' THEN 1 ELSE 0 END AS row_us,
      -- Ordering score: -1 when nothing explainable matched, so unmatched
      -- requests sort last without turning into a fabricated 0% badge.
      coalesce(CASE
        WHEN r.category_id IS NOT NULL AND r.category_id = ANY(v_declared) THEN 50
        ELSE 0
      END
      + CASE
          WHEN v_seller_area <> '' AND (
            rp.area_label ILIKE '%' || v_seller_area || '%'
            OR v_seller_area ILIKE '%' || coalesce(rp.area_label, r.city, r.region, '') || '%'
            OR r.city ILIKE '%' || v_seller_area || '%'
            OR r.region ILIKE '%' || v_seller_area || '%')
          THEN 30 ELSE 0
        END
      + CASE
          WHEN v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
               AND r.latitude IS NOT NULL
               AND hocalist.discovery_distance_miles(
                     v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)
                   <= v_radius
          THEN 20 ELSE 0
        END, -1) AS row_match,
      CASE
        WHEN v_origin.latitude IS NOT NULL AND r.latitude IS NOT NULL THEN
          round(hocalist.discovery_distance_miles(
            v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision
        ELSE NULL
      END AS row_distance,
      hocalist.discovery_lead_json(
        r.id,
        CASE
          WHEN v_origin.latitude IS NOT NULL AND r.latitude IS NOT NULL THEN
            round(hocalist.discovery_distance_miles(
              v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision
          ELSE NULL
        END,
        NULLIF(
          CASE
            WHEN r.category_id IS NOT NULL AND r.category_id = ANY(v_declared) THEN 50
            ELSE 0
          END
          + CASE
              WHEN v_seller_area <> '' AND (
                rp.area_label ILIKE '%' || v_seller_area || '%'
                OR v_seller_area ILIKE '%' || coalesce(rp.area_label, r.city, r.region, '') || '%'
                OR r.city ILIKE '%' || v_seller_area || '%'
                OR r.region ILIKE '%' || v_seller_area || '%')
              THEN 30 ELSE 0
            END
          + CASE
              WHEN v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
                   AND r.latitude IS NOT NULL
                   AND hocalist.discovery_distance_miles(
                         v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)
                       <= v_radius
              THEN 20 ELSE 0
            END,
          0),
        (
          SELECT coalesce(jsonb_agg(reason), '[]'::jsonb) FROM (
            SELECT 'Matches your declared category'::text AS reason
              WHERE r.category_id IS NOT NULL AND r.category_id = ANY(v_declared)
            UNION ALL
            SELECT 'Inside your declared service area'
              WHERE v_seller_area <> '' AND (
                rp.area_label ILIKE '%' || v_seller_area || '%'
                OR v_seller_area ILIKE '%' || coalesce(rp.area_label, r.city, r.region, '') || '%'
                OR r.city ILIKE '%' || v_seller_area || '%'
                OR r.region ILIKE '%' || v_seller_area || '%')
            UNION ALL
            SELECT 'Within your service radius'
              WHERE v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
                AND r.latitude IS NOT NULL
                AND hocalist.discovery_distance_miles(
                      v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)
                    <= v_radius
          ) reasons
        )
      ) AS row_json
    FROM hocalist.requests r
    LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = r.buyer_profile_id
    WHERE r.status = 'active'
      AND (r.acceptance_expires_at IS NULL OR now() < r.acceptance_expires_at)
      AND r.buyer_user_id <> v_user
      AND (p_kind IS NULL OR r.kind = p_kind)
      AND (p_category IS NULL OR r.category_id = p_category)
      AND (v_query IS NULL OR r.title ILIKE '%' || v_query || '%'
           OR r.description ILIKE '%' || v_query || '%')
      AND (p_budget_min_minor IS NULL
           OR coalesce(r.budget_max_minor, r.budget_min_minor) >= p_budget_min_minor)
      AND (p_budget_max_minor IS NULL
           OR coalesce(r.budget_min_minor, r.budget_max_minor) <= p_budget_max_minor)
      AND (p_area IS NULL OR rp.area_label ILIKE '%' || btrim(p_area) || '%'
           OR r.city ILIKE '%' || btrim(p_area) || '%'
           OR r.region ILIKE '%' || btrim(p_area) || '%')
      AND (v_radius IS NULL OR v_origin.latitude IS NULL OR r.latitude IS NULL
           OR hocalist.discovery_distance_miles(
                v_origin.latitude, v_origin.longitude, r.latitude, r.longitude) <= v_radius)
      AND (
        p_cursor IS NULL
        OR (v_sort = 'newest' AND (
              (extract(epoch FROM r.created_at) * 1000000)::bigint, r.id
            ) < (v_cursor_micros, v_cursor_id))
        OR (v_sort = 'closest' AND (
              coalesce(round(hocalist.discovery_distance_miles(
                v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision,
                'Infinity'::double precision) > v_cursor_metric
              OR (coalesce(round(hocalist.discovery_distance_miles(
                v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision,
                'Infinity'::double precision) = v_cursor_metric
                AND ((extract(epoch FROM r.created_at) * 1000000)::bigint, r.id)
                    < (v_cursor_micros, v_cursor_id))))
        OR (v_sort = 'budget' AND (
              coalesce(r.budget_max_minor, -1)::double precision,
              (extract(epoch FROM r.created_at) * 1000000)::bigint, r.id
            ) < (v_cursor_metric, v_cursor_micros, v_cursor_id))
        OR (v_sort = 'recommended' AND (
              coalesce(
                CASE WHEN r.category_id IS NOT NULL AND r.category_id = ANY(v_declared) THEN 50 ELSE 0 END
                + CASE
                    WHEN v_seller_area <> '' AND (
                      rp.area_label ILIKE '%' || v_seller_area || '%'
                      OR v_seller_area ILIKE '%' || coalesce(rp.area_label, r.city, r.region, '') || '%'
                      OR r.city ILIKE '%' || v_seller_area || '%'
                      OR r.region ILIKE '%' || v_seller_area || '%')
                    THEN 30 ELSE 0
                  END
                + CASE
                    WHEN v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
                         AND r.latitude IS NOT NULL
                         AND hocalist.discovery_distance_miles(
                               v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)
                             <= v_radius
                    THEN 20 ELSE 0
                  END, -1),
              CASE WHEN r.country_code = 'US' THEN 1 ELSE 0 END,
              (extract(epoch FROM r.created_at) * 1000000)::bigint,
              r.id
            ) < (v_cursor_match, v_cursor_us, v_cursor_micros, v_cursor_id))
      )
    ORDER BY
      CASE WHEN v_sort = 'recommended' THEN coalesce(
        CASE WHEN r.category_id IS NOT NULL AND r.category_id = ANY(v_declared) THEN 50 ELSE 0 END
        + CASE
            WHEN v_seller_area <> '' AND (
              rp.area_label ILIKE '%' || v_seller_area || '%'
              OR v_seller_area ILIKE '%' || coalesce(rp.area_label, r.city, r.region, '') || '%'
              OR r.city ILIKE '%' || v_seller_area || '%'
              OR r.region ILIKE '%' || v_seller_area || '%')
            THEN 30 ELSE 0
          END
        + CASE
            WHEN v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
                 AND r.latitude IS NOT NULL
                 AND hocalist.discovery_distance_miles(
                       v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)
                     <= v_radius
            THEN 20 ELSE 0
          END, -1) END DESC,
      CASE WHEN v_sort = 'recommended' THEN CASE WHEN r.country_code = 'US' THEN 1 ELSE 0 END END DESC,
      CASE WHEN v_sort = 'closest' THEN coalesce(round(hocalist.discovery_distance_miles(
        v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision,
        'Infinity'::double precision) END ASC,
      CASE WHEN v_sort = 'budget' THEN coalesce(r.budget_max_minor, -1) END DESC,
      r.created_at DESC, r.id DESC
    LIMIT v_size
  ) rows;

  v_next := NULL;
  IF jsonb_array_length(v_rows) = v_size THEN
    SELECT
      CASE WHEN v_sort = 'recommended' THEN coalesce((v_rows->-1->>'match_percent')::integer, -1) END,
      CASE WHEN v_sort = 'recommended' THEN
        CASE WHEN (SELECT r.country_code = 'US' FROM hocalist.requests r
                   WHERE r.id = (v_rows->-1->>'request_id')::uuid)
             THEN 1 ELSE 0 END
      END,
      CASE WHEN v_sort IN ('closest','budget') THEN
        CASE WHEN v_sort = 'closest'
             THEN coalesce((v_rows->-1->>'distance_miles')::double precision, 'Infinity'::double precision)
             ELSE (SELECT coalesce(r.budget_max_minor, -1)::double precision
                   FROM hocalist.requests r WHERE r.id = (v_rows->-1->>'request_id')::uuid) END
      END,
      (extract(epoch FROM r.created_at) * 1000000)::bigint, r.id
      INTO v_last_match, v_last_us, v_last_metric, v_last_micros, v_last_id
      FROM hocalist.requests r WHERE r.id = (v_rows->-1->>'request_id')::uuid;
    v_last_match := coalesce(v_last_match, -1);
    v_last_us := coalesce(v_last_us, 0);
    SELECT EXISTS (
      SELECT 1 FROM hocalist.requests r
      LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = r.buyer_profile_id
      WHERE r.status = 'active'
        AND (r.acceptance_expires_at IS NULL OR now() < r.acceptance_expires_at)
        AND r.buyer_user_id <> v_user
        AND (p_kind IS NULL OR r.kind = p_kind)
        AND (p_category IS NULL OR r.category_id = p_category)
        AND (v_query IS NULL OR r.title ILIKE '%' || v_query || '%'
             OR r.description ILIKE '%' || v_query || '%')
        AND (p_budget_min_minor IS NULL
             OR coalesce(r.budget_max_minor, r.budget_min_minor) >= p_budget_min_minor)
        AND (p_budget_max_minor IS NULL
             OR coalesce(r.budget_min_minor, r.budget_max_minor) <= p_budget_max_minor)
        AND (p_area IS NULL OR rp.area_label ILIKE '%' || btrim(p_area) || '%'
             OR r.city ILIKE '%' || btrim(p_area) || '%'
             OR r.region ILIKE '%' || btrim(p_area) || '%')
        AND (v_radius IS NULL OR v_origin.latitude IS NULL OR r.latitude IS NULL
             OR hocalist.discovery_distance_miles(
                  v_origin.latitude, v_origin.longitude, r.latitude, r.longitude) <= v_radius)
        AND (
          (v_sort = 'newest' AND
             ((extract(epoch FROM r.created_at) * 1000000)::bigint, r.id) < (v_last_micros, v_last_id))
          OR (v_sort = 'closest' AND (
             coalesce(round(hocalist.discovery_distance_miles(
                v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision,
                'Infinity'::double precision) > coalesce(v_last_metric, 'Infinity'::double precision)
             OR (coalesce(round(hocalist.discovery_distance_miles(
                v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision,
                'Infinity'::double precision) = coalesce(v_last_metric, 'Infinity'::double precision)
               AND ((extract(epoch FROM r.created_at) * 1000000)::bigint, r.id)
                   < (v_last_micros, v_last_id))))
          OR (v_sort = 'budget' AND
             (coalesce(r.budget_max_minor, -1)::double precision,
              (extract(epoch FROM r.created_at) * 1000000)::bigint, r.id)
             < (coalesce(v_last_metric, -1), v_last_micros, v_last_id))
          OR (v_sort = 'recommended' AND
             (coalesce(
                CASE WHEN r.category_id IS NOT NULL AND r.category_id = ANY(v_declared) THEN 50 ELSE 0 END
                + CASE
                    WHEN v_seller_area <> '' AND (
                      rp.area_label ILIKE '%' || v_seller_area || '%'
                      OR v_seller_area ILIKE '%' || coalesce(rp.area_label, r.city, r.region, '') || '%'
                      OR r.city ILIKE '%' || v_seller_area || '%'
                      OR r.region ILIKE '%' || v_seller_area || '%')
                    THEN 30 ELSE 0
                  END
                + CASE
                    WHEN v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
                         AND r.latitude IS NOT NULL
                         AND hocalist.discovery_distance_miles(
                               v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)
                             <= v_radius
                    THEN 20 ELSE 0
                  END, -1),
              CASE WHEN r.country_code = 'US' THEN 1 ELSE 0 END,
              (extract(epoch FROM r.created_at) * 1000000)::bigint,
              r.id
             ) < (v_last_match, v_last_us, v_last_micros, v_last_id))
        )
    ) INTO v_has_more;
    IF v_has_more THEN
      v_next := CASE v_sort
        WHEN 'recommended' THEN
          'recommended|' || v_last_match::text || '|' || v_last_us::text || '|'
          || v_last_micros::text || '|' || v_last_id::text
        WHEN 'closest' THEN
          'closest|' || v_last_metric::text || '|' || v_last_micros::text || '|' || v_last_id::text
        WHEN 'budget' THEN
          'budget|' || v_last_metric::text || '|' || v_last_micros::text || '|' || v_last_id::text
        ELSE 'newest|' || v_last_micros::text || '|' || v_last_id::text
      END;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'items', v_rows,
    'next_cursor', v_next,
    'sort', v_sort,
    'applied_radius_miles', v_radius,
    'distance_available', v_origin.latitude IS NOT NULL,
    'manual_area_fallback', v_origin.latitude IS NULL,
    'declared_category_count', coalesce(array_length(v_declared, 1), 0),
    'us_priority_applied', v_sort = 'recommended');
END $$;

-- Stable discovery ordering indexes. The existing request indexes order by
-- (status, created_at, id); these add the category-scoped candidate path.
CREATE INDEX requests_discovery_order
  ON hocalist.requests(created_at DESC, id DESC) WHERE status = 'active';
CREATE INDEX requests_discovery_category
  ON hocalist.requests(category_id, created_at DESC, id DESC) WHERE status = 'active';

REVOKE ALL ON FUNCTION hocalist.discovery_declared_category_ids(uuid),
  hocalist.discovery_assert_active_member(uuid),
  hocalist.discovery_origin_json(), hocalist.discovery_origin_set(text,jsonb),
  hocalist.discovery_lead_json(uuid,double precision,integer,jsonb),
  hocalist.marketplace_discovery_leads(text,uuid,text,integer,text,text,integer,text,bigint,bigint)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.discovery_origin_json(),
  hocalist.discovery_origin_set(text,jsonb),
  hocalist.marketplace_discovery_leads(text,uuid,text,integer,text,text,integer,text,bigint,bigint)
  TO authenticated;
COMMIT;


-- ===========================================================================
-- 141_recommended_leads.sql
-- ===========================================================================
-- Additive recommended-leads read over discovery_completion/140.
--
-- The seller home "Recommended leads for you" section previously had no
-- projection and stayed permanently empty in real mode. This read returns
-- eligible requests explained by the seller's declared Store-listing
-- categories and declared service area/radius. Every returned card carries
-- its match reasons, so the UI never shows an unexplained percentage or a
-- fixed fixture.
--
-- Prerequisite: discovery_completion/140 (same package).
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

DO $guard$ BEGIN
  IF to_regprocedure('hocalist.discovery_declared_category_ids(uuid)') IS NULL
     OR to_regprocedure('hocalist.discovery_lead_json(uuid,double precision,integer,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'discovery leads 140 prerequisite missing';
  END IF;
  IF to_regprocedure('hocalist.marketplace_recommended_leads(integer)') IS NOT NULL THEN
    RAISE EXCEPTION 'recommended leads already installed';
  END IF;
END; $guard$;

CREATE FUNCTION hocalist.marketplace_recommended_leads(p_limit integer DEFAULT 6)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_size integer;
  v_origin hocalist.seller_discovery_origins%ROWTYPE;
  v_radius integer;
  v_declared uuid[];
  v_declared_labels jsonb;
  v_seller_area text;
  v_has_basis boolean;
  v_items jsonb;
BEGIN
  PERFORM hocalist.marketplace_assert_role(v_user, 'seller');
  v_size := greatest(1, least(coalesce(p_limit, 6), 20));
  SELECT * INTO v_origin FROM hocalist.seller_discovery_origins WHERE seller_user_id = v_user;
  IF NOT FOUND THEN
    v_origin.radius_miles := NULL;
  END IF;
  v_radius := v_origin.radius_miles;
  SELECT coalesce(rp.area_label, '') INTO v_seller_area
    FROM hocalist.memberships m
    LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = m.id
    WHERE m.user_id = v_user AND m.role = 'seller' AND m.status = 'active'
    LIMIT 1;
  v_seller_area := coalesce(v_seller_area, '');
  v_declared := hocalist.discovery_declared_category_ids(v_user);
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'label', c.label)
                            ORDER BY c.label, c.id), '[]'::jsonb)
    INTO v_declared_labels
    FROM hocalist.catalogue_categories c
    WHERE c.id = ANY(v_declared);
  v_has_basis := coalesce(array_length(v_declared, 1), 0) > 0
    OR v_seller_area <> ''
    OR v_radius IS NOT NULL;

  IF NOT v_has_basis THEN
    RETURN jsonb_build_object(
      'items', '[]'::jsonb,
      'basis', jsonb_build_object(
        'declared_categories', '[]'::jsonb,
        'area_label', NULL,
        'radius_miles', NULL),
      'unavailable_reason', 'no_matching_basis');
  END IF;

  SELECT coalesce(jsonb_agg(row_json ORDER BY row_match DESC, row_us DESC,
                            row_micros DESC, row_id DESC), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT
      r.id AS row_id,
      (extract(epoch FROM r.created_at) * 1000000)::bigint AS row_micros,
      CASE WHEN r.country_code = 'US' THEN 1 ELSE 0 END AS row_us,
      coalesce(match_expr, -1) AS row_match,
      hocalist.discovery_lead_json(
        r.id,
        CASE
          WHEN v_origin.latitude IS NOT NULL AND r.latitude IS NOT NULL THEN
            round(hocalist.discovery_distance_miles(
              v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)::numeric, 1)::double precision
          ELSE NULL
        END,
        match_expr,
        (
          SELECT coalesce(jsonb_agg(reason), '[]'::jsonb) FROM (
            SELECT 'Matches your declared category'::text AS reason
              WHERE r.category_id IS NOT NULL AND r.category_id = ANY(v_declared)
            UNION ALL
            SELECT 'Inside your declared service area'
              WHERE v_seller_area <> '' AND (
                rp.area_label ILIKE '%' || v_seller_area || '%'
                OR v_seller_area ILIKE '%' || coalesce(rp.area_label, r.city, r.region, '') || '%'
                OR r.city ILIKE '%' || v_seller_area || '%'
                OR r.region ILIKE '%' || v_seller_area || '%')
            UNION ALL
            SELECT 'Within your service radius'
              WHERE v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
                AND r.latitude IS NOT NULL
                AND hocalist.discovery_distance_miles(
                      v_origin.latitude, v_origin.longitude, r.latitude, r.longitude)
                    <= v_radius
          ) reasons
        )
      ) AS row_json
    FROM (
      SELECT r0.*,
        (
          CASE WHEN r0.category_id IS NOT NULL AND r0.category_id = ANY(v_declared) THEN 50 ELSE 0 END
          + CASE
              WHEN v_seller_area <> '' AND (
                rp0.area_label ILIKE '%' || v_seller_area || '%'
                OR v_seller_area ILIKE '%' || coalesce(rp0.area_label, r0.city, r0.region, '') || '%'
                OR r0.city ILIKE '%' || v_seller_area || '%'
                OR r0.region ILIKE '%' || v_seller_area || '%')
              THEN 30 ELSE 0
            END
          + CASE
              WHEN v_radius IS NOT NULL AND v_origin.latitude IS NOT NULL
                   AND r0.latitude IS NOT NULL
                   AND hocalist.discovery_distance_miles(
                         v_origin.latitude, v_origin.longitude, r0.latitude, r0.longitude)
                       <= v_radius
              THEN 20 ELSE 0
            END
        ) AS match_order
      FROM hocalist.requests r0
      LEFT JOIN hocalist.role_profiles rp0 ON rp0.membership_id = r0.buyer_profile_id
      WHERE r0.status = 'active'
        AND (r0.acceptance_expires_at IS NULL OR now() < r0.acceptance_expires_at)
        AND r0.buyer_user_id <> v_user
    ) r
    LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = r.buyer_profile_id,
    LATERAL (SELECT NULLIF(r.match_order, 0) AS match_expr) scored
    WHERE match_expr IS NOT NULL
    LIMIT v_size
  ) rows;

  RETURN jsonb_build_object(
    'items', v_items,
    'basis', jsonb_build_object(
      'declared_categories', v_declared_labels,
      'area_label', nullif(v_seller_area, ''),
      'radius_miles', v_radius),
    'unavailable_reason', CASE
      WHEN jsonb_array_length(v_items) = 0 THEN 'no_eligible_matches'
      ELSE NULL END);
END $$;

REVOKE ALL ON FUNCTION hocalist.marketplace_recommended_leads(integer)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.marketplace_recommended_leads(integer)
  TO authenticated;
COMMIT;


-- ===========================================================================
-- 142_reviews.sql
-- ===========================================================================
-- Additive post-purchase review contract.
--
-- Eligibility comes only from a confirmed purchase (`sale_confirmations`): the
-- buyer of that outcome may create exactly one authoritative review per
-- request. Submission is idempotent; a replay with the same intent key and
-- payload returns the stored review, a changed payload on the same key is a
-- conflict, and a second review for the same outcome is refused. Moderation is
-- a recorded server decision with a reason; the public aggregate exposes only
-- published reviews and never a buyer identity beyond the consented label
-- helper.
--
-- Prerequisites: marketplace/020 + meetings/040 + outcomes/080 (sale
-- confirmations). Review submissions and reads stay behind
-- `kDiscoveryCompletionEnabled` in the app until this package is deployed.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

DO $guard$ BEGIN
  IF to_regclass('hocalist.sale_confirmations') IS NULL
     OR to_regclass('hocalist.marketplace_receipts') IS NULL
     OR to_regprocedure('hocalist.marketplace_assert_role(uuid,text)') IS NULL
     OR to_regprocedure('hocalist.discovery_assert_active_member(uuid)') IS NULL THEN
    RAISE EXCEPTION 'outcomes 080 / marketplace 020 / discovery 140 prerequisite missing';
  END IF;
  IF to_regclass('hocalist.outcome_reviews') IS NOT NULL THEN
    RAISE EXCEPTION 'reviews already installed';
  END IF;
END; $guard$;

CREATE TABLE hocalist.outcome_reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_id uuid NOT NULL UNIQUE REFERENCES hocalist.requests(id),
  meeting_id uuid NOT NULL REFERENCES hocalist.meetings(id),
  offer_id uuid NOT NULL REFERENCES hocalist.offers(id),
  buyer_user_id uuid NOT NULL REFERENCES hocalist.profiles(id),
  seller_user_id uuid NOT NULL REFERENCES hocalist.profiles(id),
  seller_profile_id uuid NOT NULL REFERENCES hocalist.memberships(id),
  rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
  body text NOT NULL DEFAULT '' CHECK (length(body) <= 1500),
  status text NOT NULL DEFAULT 'published'
    CHECK (status IN ('published','hidden','removed')),
  moderation_reason text
    CHECK (moderation_reason IS NULL OR length(btrim(moderation_reason)) BETWEEN 1 AND 500),
  moderated_by uuid REFERENCES hocalist.profiles(id),
  moderated_at timestamptz,
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT review_moderation_shape CHECK (
    (moderated_by IS NULL AND moderated_at IS NULL)
    OR (moderated_by IS NOT NULL AND moderation_reason IS NOT NULL)
  )
);
CREATE INDEX outcome_reviews_seller_public
  ON hocalist.outcome_reviews(seller_profile_id, created_at DESC, id DESC)
  WHERE status = 'published';
ALTER TABLE hocalist.outcome_reviews ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hocalist.outcome_reviews FROM PUBLIC, anon, authenticated, service_role;

-- Reviewer label is masked unless a separately reviewed public-profile
-- consent table exists and the buyer explicitly opted in. This wrapper keeps
-- the reviews package independently applicable before 143 ships.
CREATE FUNCTION hocalist.review_reviewer_label(p_user uuid)
RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_label text;
BEGIN
  IF to_regclass('hocalist.buyer_public_profile_consent') IS NOT NULL THEN
    EXECUTE
      'SELECT CASE WHEN c.is_public AND c.show_display_name
              THEN coalesce(nullif(btrim(rp.display_name), ''''), ''Hocalist buyer'')
              ELSE ''Hocalist buyer'' END
         FROM hocalist.buyer_public_profile_consent c
         LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = (
           SELECT m.id FROM hocalist.memberships m
           WHERE m.user_id = c.user_id AND m.role = ''buyer''
           ORDER BY m.created_at, m.id LIMIT 1)
        WHERE c.user_id = $1'
      INTO v_label USING p_user;
  END IF;
  RETURN coalesce(v_label, 'Hocalist buyer');
END $$;

CREATE FUNCTION hocalist.review_json(p_review uuid)
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT jsonb_build_object(
    'id', v.id,
    'request_id', v.request_id,
    'rating', v.rating,
    'body', v.body,
    'status', v.status,
    'revision', v.revision,
    'created_at', v.created_at,
    'updated_at', v.updated_at,
    'moderation_reason', CASE WHEN v.status = 'published' THEN NULL ELSE v.moderation_reason END)
  FROM hocalist.outcome_reviews v WHERE v.id = p_review;
$$;

-- Buyer eligibility and their authoritative review, if any.
CREATE FUNCTION hocalist.review_status(p_request uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  o hocalist.sale_confirmations%ROWTYPE;
  v hocalist.outcome_reviews%ROWTYPE;
BEGIN
  PERFORM hocalist.marketplace_assert_role(u, 'buyer');
  IF p_request IS NULL THEN RAISE EXCEPTION 'invalid_request' USING ERRCODE='22023'; END IF;
  SELECT * INTO o FROM hocalist.sale_confirmations WHERE request_id = p_request;
  IF NOT FOUND OR o.buyer_user_id <> u THEN
    RETURN jsonb_build_object(
      'eligible', false,
      'reason', CASE WHEN NOT FOUND THEN 'not_confirmed' ELSE 'not_participant' END,
      'request_id', p_request,
      'review', NULL);
  END IF;
  SELECT * INTO v FROM hocalist.outcome_reviews WHERE request_id = p_request;
  RETURN jsonb_build_object(
    'eligible', true,
    'reason', 'confirmed_purchase',
    'request_id', p_request,
    'outcome_id', o.id,
    'review', CASE WHEN FOUND THEN hocalist.review_json(v.id) ELSE NULL END);
END $$;

-- One authoritative review per confirmed purchase. Idempotent by intent key.
CREATE FUNCTION hocalist.review_submit(p_key text, p_input jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  h text;
  receipt hocalist.marketplace_receipts%ROWTYPE;
  o hocalist.sale_confirmations%ROWTYPE;
  existing hocalist.outcome_reviews%ROWTYPE;
  v hocalist.outcome_reviews%ROWTYPE;
  v_rating integer;
  v_body text;
BEGIN
  PERFORM hocalist.marketplace_assert_role(u, 'buyer');
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 128
     OR p_input IS NULL OR jsonb_typeof(p_input) <> 'object'
     OR p_input - ARRAY['request_id','rating','body'] <> '{}'::jsonb
     OR jsonb_typeof(p_input->'rating') <> 'number'
     OR (p_input->>'rating') !~ '^[1-5]$'
     OR jsonb_typeof(p_input->'body') IS DISTINCT FROM 'string'
     OR length(coalesce(p_input->>'body','')) > 1500 THEN
    RAISE EXCEPTION 'invalid_review' USING ERRCODE='22023';
  END IF;
  v_rating := (p_input->>'rating')::integer;
  v_body := btrim(coalesce(p_input->>'body',''));
  -- Authorization precedes the receipt so a restricted account can never
  -- replay a stored acknowledgement.
  SELECT * INTO o FROM hocalist.sale_confirmations
    WHERE request_id = (p_input->>'request_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'review_not_eligible' USING ERRCODE='P0001'; END IF;
  IF o.buyer_user_id <> u THEN RAISE EXCEPTION 'review_not_eligible' USING ERRCODE='42501'; END IF;
  h := encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(u::text||':review:'||p_key,0));
  SELECT * INTO receipt FROM hocalist.marketplace_receipts
    WHERE user_id = u AND operation = 'review.submit' AND idempotency_key = p_key;
  IF FOUND THEN
    IF receipt.request_hash <> h THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001'; END IF;
    RETURN receipt.result;
  END IF;
  SELECT * INTO o FROM hocalist.sale_confirmations
    WHERE request_id = (p_input->>'request_id')::uuid FOR UPDATE;
  IF NOT FOUND OR o.buyer_user_id <> u THEN
    RAISE EXCEPTION 'review_not_eligible' USING ERRCODE='42501';
  END IF;
  SELECT * INTO existing FROM hocalist.outcome_reviews WHERE request_id = o.request_id;
  IF FOUND THEN
    -- A retry with the same content is a replay; changed content is refused so
    -- one outcome never accumulates two authoritative reviews.
    IF existing.rating = v_rating AND existing.body = v_body THEN
      INSERT INTO hocalist.marketplace_receipts(user_id, operation, idempotency_key, request_hash, result)
      VALUES (u, 'review.submit', p_key, h, hocalist.review_json(existing.id));
      RETURN hocalist.review_json(existing.id);
    END IF;
    RAISE EXCEPTION 'review_exists' USING ERRCODE='P0001';
  END IF;
  INSERT INTO hocalist.outcome_reviews(
    request_id, meeting_id, offer_id, buyer_user_id, seller_user_id, seller_profile_id, rating, body)
  VALUES (o.request_id, o.meeting_id, o.offer_id, o.buyer_user_id, o.seller_user_id,
          (SELECT m.id FROM hocalist.memberships m
           WHERE m.user_id = o.seller_user_id AND m.role = 'seller' LIMIT 1),
          v_rating, v_body)
  RETURNING * INTO v;
  INSERT INTO hocalist.marketplace_receipts(user_id, operation, idempotency_key, request_hash, result)
  VALUES (u, 'review.submit', p_key, h, hocalist.review_json(v.id));
  RETURN hocalist.review_json(v.id);
END $$;

-- Buyer edit of their own authoritative review at an expected revision.
CREATE FUNCTION hocalist.review_update(p_key text, p_input jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  h text;
  receipt hocalist.marketplace_receipts%ROWTYPE;
  v hocalist.outcome_reviews%ROWTYPE;
  v_rating integer;
  v_body text;
BEGIN
  PERFORM hocalist.marketplace_assert_role(u, 'buyer');
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 128
     OR p_input IS NULL OR jsonb_typeof(p_input) <> 'object'
     OR p_input - ARRAY['review_id','expected_revision','rating','body'] <> '{}'::jsonb
     OR jsonb_typeof(p_input->'rating') <> 'number'
     OR (p_input->>'rating') !~ '^[1-5]$'
     OR jsonb_typeof(p_input->'body') IS DISTINCT FROM 'string'
     OR length(coalesce(p_input->>'body','')) > 1500
     OR jsonb_typeof(p_input->'expected_revision') <> 'number' THEN
    RAISE EXCEPTION 'invalid_review' USING ERRCODE='22023';
  END IF;
  v_rating := (p_input->>'rating')::integer;
  v_body := btrim(coalesce(p_input->>'body',''));
  h := encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(u::text||':review_update:'||p_key,0));
  SELECT * INTO receipt FROM hocalist.marketplace_receipts
    WHERE user_id = u AND operation = 'review.update' AND idempotency_key = p_key;
  IF FOUND THEN
    IF receipt.request_hash <> h THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001'; END IF;
    RETURN receipt.result;
  END IF;
  UPDATE hocalist.outcome_reviews SET rating = v_rating, body = v_body,
    revision = revision + 1, updated_at = now()
  WHERE id = (p_input->>'review_id')::uuid AND buyer_user_id = u
    AND status <> 'removed'
    AND revision = (p_input->>'expected_revision')::bigint
  RETURNING * INTO v;
  IF NOT FOUND THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='P0001'; END IF;
  INSERT INTO hocalist.marketplace_receipts(user_id, operation, idempotency_key, request_hash, result)
  VALUES (u, 'review.update', p_key, h, hocalist.review_json(v.id));
  RETURN hocalist.review_json(v.id);
END $$;

-- Recorded moderation decision. Admin-only; no automatic penalty is implied.
CREATE FUNCTION hocalist.review_moderate(p_key text, p_input jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  h text;
  receipt hocalist.marketplace_receipts%ROWTYPE;
  v hocalist.outcome_reviews%ROWTYPE;
BEGIN
  PERFORM hocalist.marketplace_assert_admin(u);
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 128
     OR p_input IS NULL OR jsonb_typeof(p_input) <> 'object'
     OR p_input - ARRAY['review_id','expected_revision','status','reason'] <> '{}'::jsonb
     OR p_input->>'status' NOT IN ('published','hidden','removed')
     OR jsonb_typeof(p_input->'reason') IS DISTINCT FROM 'string'
     OR length(btrim(p_input->>'reason')) NOT BETWEEN 1 AND 500
     OR jsonb_typeof(p_input->'expected_revision') <> 'number' THEN
    RAISE EXCEPTION 'invalid_moderation' USING ERRCODE='22023';
  END IF;
  h := encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(u::text||':review_moderate:'||p_key,0));
  SELECT * INTO receipt FROM hocalist.marketplace_receipts
    WHERE user_id = u AND operation = 'review.moderate' AND idempotency_key = p_key;
  IF FOUND THEN
    IF receipt.request_hash <> h THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001'; END IF;
    RETURN receipt.result;
  END IF;
  UPDATE hocalist.outcome_reviews SET status = p_input->>'status',
    moderation_reason = btrim(p_input->>'reason'),
    moderated_by = u, moderated_at = now(),
    revision = revision + 1, updated_at = now()
  WHERE id = (p_input->>'review_id')::uuid
    AND revision = (p_input->>'expected_revision')::bigint
  RETURNING * INTO v;
  IF NOT FOUND THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='P0001'; END IF;
  INSERT INTO hocalist.marketplace_receipts(user_id, operation, idempotency_key, request_hash, result)
  VALUES (u, 'review.moderate', p_key, h, hocalist.review_json(v.id));
  RETURN hocalist.review_json(v.id);
END $$;

-- Public seller reputation. Only published reviews and verified purchase
-- counts are aggregated; no buyer auth identity, contacts or exact address is
-- exposed. Reviewer labels stay masked until the buyer opts in through the
-- separately reviewed consent contract. A restricted or disabled target is
-- not publicly promotable, so its projection is withheld.
CREATE FUNCTION hocalist.seller_public_reputation(p_seller_profile uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  v_user uuid;
  v_sum integer;
  v_count integer;
BEGIN
  PERFORM hocalist.discovery_assert_active_member(u);
  IF p_seller_profile IS NULL THEN RAISE EXCEPTION 'invalid_profile' USING ERRCODE='22023'; END IF;
  SELECT m.user_id INTO v_user FROM hocalist.memberships m
    WHERE m.id = p_seller_profile AND m.role = 'seller';
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'seller_profile_id', p_seller_profile,
      'available', false,
      'reason', 'profile_not_found',
      'rating_sum', 0, 'rating_count', 0, 'completed_deals', 0,
      'reviews', '[]'::jsonb);
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships m2
             WHERE m2.user_id = v_user AND m2.status IN ('restricted','disabled')) THEN
    RETURN jsonb_build_object(
      'seller_profile_id', p_seller_profile,
      'available', false,
      'reason', 'target_unavailable',
      'rating_sum', 0, 'rating_count', 0, 'completed_deals', 0,
      'reviews', '[]'::jsonb);
  END IF;
  SELECT coalesce(sum(r.rating), 0)::integer, count(*)::integer
    INTO v_sum, v_count
    FROM hocalist.outcome_reviews r
    WHERE r.seller_profile_id = p_seller_profile AND r.status = 'published';
  RETURN jsonb_build_object(
    'seller_profile_id', p_seller_profile,
    'available', true,
    'reason', NULL,
    'rating_sum', v_sum,
    'rating_count', v_count,
    'completed_deals', (
      SELECT count(*)::integer FROM hocalist.sale_confirmations s
      WHERE s.seller_user_id = v_user),
    'reviews', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id, 'rating', r.rating, 'body', r.body,
        'created_at', r.created_at,
        'reviewer_label', hocalist.review_reviewer_label(r.buyer_user_id))
        ORDER BY r.created_at DESC, r.id DESC)
      FROM (SELECT * FROM hocalist.outcome_reviews
            WHERE seller_profile_id = p_seller_profile AND status = 'published'
            ORDER BY created_at DESC, id DESC LIMIT 5) r), '[]'::jsonb));
END $$;

REVOKE ALL ON FUNCTION hocalist.review_reviewer_label(uuid), hocalist.review_json(uuid),
  hocalist.review_status(uuid), hocalist.review_submit(text,jsonb),
  hocalist.review_update(text,jsonb), hocalist.review_moderate(text,jsonb),
  hocalist.seller_public_reputation(uuid)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.review_status(uuid), hocalist.review_submit(text,jsonb),
  hocalist.review_update(text,jsonb), hocalist.seller_public_reputation(uuid)
  TO authenticated;
GRANT EXECUTE ON FUNCTION hocalist.review_moderate(text,jsonb) TO authenticated;
COMMIT;


-- ===========================================================================
-- 143_trends_consent.sql
-- ===========================================================================
-- Additive Hocatrends and Winners projections plus buyer public-profile
-- consent.
--
-- Trends are computed from verified marketplace activity only: open requests,
-- sellers who actually submitted offers, and confirmed purchases inside a
-- fixed 30-day window. No competition percentage, seller count or ranking is
-- invented and no topic is hardcoded; topics are the admin-managed active
-- catalogue categories.
--
-- The buyer public profile starts closed. It is exposed only after the buyer
-- explicitly opts in and only for the individually enabled fields; field and
-- visibility consent stays conservative until the owner settles the exact
-- public-field policy, so this projection is gated off in app composition.
--
-- Prerequisites: marketplace/020 + 021 + 023, outcomes/080, and
-- discovery_completion/140 for the shared match helpers.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

DO $guard$ BEGIN
  IF to_regclass('hocalist.catalogue_categories') IS NULL
     OR to_regclass('hocalist.offers') IS NULL
     OR to_regclass('hocalist.sale_confirmations') IS NULL
     OR to_regprocedure('hocalist.discovery_assert_active_member(uuid)') IS NULL THEN
    RAISE EXCEPTION 'marketplace/outcomes/140 prerequisite missing';
  END IF;
  IF to_regclass('hocalist.buyer_public_profile_consent') IS NOT NULL
     OR to_regprocedure('hocalist.hocatrends_trends(integer)') IS NOT NULL THEN
    RAISE EXCEPTION 'Hocatrends projections already installed';
  END IF;
END; $guard$;

-- ---------------------------------------------------------------------------
-- Buyer public profile consent (closed by default)
-- ---------------------------------------------------------------------------

CREATE TABLE hocalist.buyer_public_profile_consent (
  user_id uuid PRIMARY KEY REFERENCES hocalist.profiles(id),
  is_public boolean NOT NULL DEFAULT false,
  show_display_name boolean NOT NULL DEFAULT false,
  show_area boolean NOT NULL DEFAULT false,
  show_categories boolean NOT NULL DEFAULT false,
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE hocalist.buyer_public_profile_consent ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hocalist.buyer_public_profile_consent FROM PUBLIC, anon, authenticated, service_role;

CREATE FUNCTION hocalist.buyer_public_profile_consent_json()
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  c hocalist.buyer_public_profile_consent%ROWTYPE;
BEGIN
  PERFORM hocalist.marketplace_assert_role(u, 'buyer');
  SELECT * INTO c FROM hocalist.buyer_public_profile_consent WHERE user_id = u;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'is_public', false, 'show_display_name', false,
      'show_area', false, 'show_categories', false, 'revision', 0);
  END IF;
  RETURN jsonb_build_object(
    'is_public', c.is_public,
    'show_display_name', c.show_display_name,
    'show_area', c.show_area,
    'show_categories', c.show_categories,
    'revision', c.revision);
END $$;

-- Explicit opt-in only. Every visibility flag is required so a partial or
-- accidental public state cannot be created.
CREATE FUNCTION hocalist.buyer_public_profile_consent_set(p_key text, p_input jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  h text;
  receipt hocalist.marketplace_receipts%ROWTYPE;
  c hocalist.buyer_public_profile_consent%ROWTYPE;
BEGIN
  PERFORM hocalist.marketplace_assert_role(u, 'buyer');
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 128
     OR p_input IS NULL OR jsonb_typeof(p_input) <> 'object'
     OR p_input - ARRAY['is_public','show_display_name','show_area','show_categories'] <> '{}'::jsonb
     OR jsonb_typeof(p_input->'is_public') <> 'boolean'
     OR jsonb_typeof(p_input->'show_display_name') <> 'boolean'
     OR jsonb_typeof(p_input->'show_area') <> 'boolean'
     OR jsonb_typeof(p_input->'show_categories') <> 'boolean' THEN
    RAISE EXCEPTION 'invalid_consent' USING ERRCODE='22023';
  END IF;
  h := encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(u::text||':buyer_consent:'||p_key,0));
  SELECT * INTO receipt FROM hocalist.marketplace_receipts
    WHERE user_id = u AND operation = 'buyer_public.consent_set' AND idempotency_key = p_key;
  IF FOUND THEN
    IF receipt.request_hash <> h THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001'; END IF;
    RETURN receipt.result;
  END IF;
  INSERT INTO hocalist.buyer_public_profile_consent(
    user_id, is_public, show_display_name, show_area, show_categories)
  VALUES (u,
    (p_input->>'is_public')::boolean,
    (p_input->>'show_display_name')::boolean,
    (p_input->>'show_area')::boolean,
    (p_input->>'show_categories')::boolean)
  ON CONFLICT (user_id) DO UPDATE SET
    is_public = excluded.is_public,
    show_display_name = excluded.show_display_name,
    show_area = excluded.show_area,
    show_categories = excluded.show_categories,
    revision = hocalist.buyer_public_profile_consent.revision + 1,
    updated_at = now()
  RETURNING * INTO c;
  INSERT INTO hocalist.marketplace_receipts(user_id, operation, idempotency_key, request_hash, result)
  VALUES (u, 'buyer_public.consent_set', p_key, h, jsonb_build_object(
    'is_public', c.is_public,
    'show_display_name', c.show_display_name,
    'show_area', c.show_area,
    'show_categories', c.show_categories,
    'revision', c.revision));
  RETURN jsonb_build_object(
    'is_public', c.is_public,
    'show_display_name', c.show_display_name,
    'show_area', c.show_area,
    'show_categories', c.show_categories,
    'revision', c.revision);
END $$;

-- Consented public projection. Returns `available = false` unless the buyer
-- opted in; individual fields stay null unless individually enabled. Never
-- includes email, phone, exact address, coordinates or documents.
CREATE FUNCTION hocalist.buyer_public_profile(p_profile uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  c hocalist.buyer_public_profile_consent%ROWTYPE;
  v_target uuid;
  v_name text;
  v_area text;
  v_categories jsonb;
BEGIN
  PERFORM hocalist.discovery_assert_active_member(u);
  IF p_profile IS NULL THEN RAISE EXCEPTION 'invalid_profile' USING ERRCODE='22023'; END IF;
  SELECT m.user_id INTO v_target FROM hocalist.memberships m
    WHERE m.id = p_profile AND m.role = 'buyer';
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'available', false, 'profile_id', p_profile,
      'reason', 'profile_not_found');
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships m2
             WHERE m2.user_id = v_target AND m2.status IN ('restricted','disabled')) THEN
    RETURN jsonb_build_object(
      'available', false, 'profile_id', p_profile,
      'reason', 'target_unavailable');
  END IF;
  SELECT * INTO c FROM hocalist.buyer_public_profile_consent
    WHERE user_id = v_target;
  IF NOT FOUND OR NOT c.is_public THEN
    RETURN jsonb_build_object(
      'available', false, 'profile_id', p_profile,
      'reason', 'consent_withheld');
  END IF;
  SELECT nullif(btrim(rp.display_name), ''), rp.area_label
    INTO v_name, v_area
    FROM hocalist.role_profiles rp WHERE rp.membership_id = p_profile;
  SELECT coalesce(jsonb_agg(DISTINCT c2.label ORDER BY c2.label), '[]'::jsonb)
    INTO v_categories
    FROM hocalist.requests r
    JOIN hocalist.catalogue_categories c2 ON c2.id = r.category_id
    WHERE r.buyer_profile_id = p_profile;
  RETURN jsonb_build_object(
    'available', true,
    'profile_id', p_profile,
    'role', 'buyer',
    'display_name', CASE WHEN c.show_display_name THEN v_name ELSE NULL END,
    'area_label', CASE WHEN c.show_area THEN v_area ELSE NULL END,
    'categories', CASE WHEN c.show_categories THEN v_categories ELSE '[]'::jsonb END,
    'member_since', (SELECT min(m.created_at) FROM hocalist.memberships m
                     WHERE m.id = p_profile AND m.role = 'buyer'),
    'verified_purchase_count', (
      SELECT count(*)::integer FROM hocalist.sale_confirmations s
      WHERE s.buyer_user_id = (
        SELECT m.user_id FROM hocalist.memberships m
        WHERE m.id = p_profile AND m.role = 'buyer')));
END $$;

-- ---------------------------------------------------------------------------
-- Hocatrends projections
-- ---------------------------------------------------------------------------

-- Demand and competition from verified activity in a fixed 30-day window.
-- `percent` is the topic's share of currently open requests, not a fabricated
-- score. Competition levels are derived from the real number of sellers who
-- submitted offers in the window.
CREATE FUNCTION hocalist.hocatrends_trends(p_limit integer DEFAULT 10)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  v_size integer;
  v_total integer;
  v_items jsonb;
BEGIN
  PERFORM hocalist.discovery_assert_active_member(u);
  v_size := greatest(1, least(coalesce(p_limit, 10), 30));
  SELECT count(*)::integer INTO v_total
    FROM hocalist.requests r
    WHERE r.status = 'active'
      AND (r.acceptance_expires_at IS NULL OR now() < r.acceptance_expires_at)
      AND r.category_id IS NOT NULL;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'rank', row_number,
      'category_id', category_id,
      'label', label,
      'open_requests', open_requests,
      'competing_sellers', competing_sellers,
      'confirmed_purchases', confirmed_purchases,
      'participating_buyers', participating_buyers,
      'percent', percent,
      'competition', CASE
        WHEN competing_sellers >= 5 THEN 'Very High'
        WHEN competing_sellers >= 3 THEN 'High'
        WHEN competing_sellers >= 1 THEN 'Medium'
        ELSE 'New' END,
      'activity_copy', CASE
        WHEN competing_sellers = 0 AND confirmed_purchases = 0
          THEN 'No competing offers in the last 30 days.'
        ELSE competing_sellers::text || ' seller'
             || CASE WHEN competing_sellers = 1 THEN '' ELSE 's' END
             || ' competing · ' || confirmed_purchases::text
             || ' confirmed purchase' || CASE WHEN confirmed_purchases = 1 THEN '' ELSE 's' END END,
      'verified_activity', true)
      ORDER BY open_requests DESC, percent DESC, label), '[]'::jsonb)
    INTO v_items
    FROM (
      SELECT
        t.id AS category_id,
        t.label AS label,
        t.open_requests,
        t.competing_sellers,
        t.confirmed_purchases,
        t.participating_buyers,
        CASE WHEN v_total = 0 THEN 0
             ELSE round(100.0 * t.open_requests / v_total)::integer END AS percent,
        row_number() OVER (ORDER BY t.open_requests DESC, t.label) AS row_number
      FROM (
        SELECT
          c.id,
          c.label,
          (SELECT count(*)::integer FROM hocalist.requests r
            WHERE r.category_id = c.id AND r.status = 'active'
              AND (r.acceptance_expires_at IS NULL OR now() < r.acceptance_expires_at)) AS open_requests,
          (SELECT count(DISTINCT o.seller_user_id)::integer
             FROM hocalist.offers o JOIN hocalist.requests r2 ON r2.id = o.request_id
            WHERE r2.category_id = c.id
              AND o.status IN ('submitted','selected','completed')
              AND o.created_at > now() - interval '30 days') AS competing_sellers,
          (SELECT count(*)::integer
             FROM hocalist.sale_confirmations s JOIN hocalist.requests r3 ON r3.id = s.request_id
            WHERE r3.category_id = c.id
              AND s.confirmed_at > now() - interval '30 days') AS confirmed_purchases,
          (SELECT count(DISTINCT r4.buyer_user_id)::integer FROM hocalist.requests r4
            WHERE r4.category_id = c.id
              AND r4.created_at > now() - interval '30 days') AS participating_buyers
        FROM hocalist.catalogue_categories c
        WHERE c.status = 'active'
      ) t
      WHERE t.open_requests > 0 OR t.competing_sellers > 0 OR t.confirmed_purchases > 0
      ORDER BY t.open_requests DESC, t.label
      LIMIT v_size
    ) topics;
  RETURN jsonb_build_object(
    'window_days', 30,
    'generated_at', now(),
    'open_request_total', v_total,
    'items', v_items);
END $$;

-- Winners: recent confirmed purchases. Buyer identity and area are masked
-- unless the buyer opted in through the consent contract; private offers,
-- contacts and exact locations are never projected.
CREATE FUNCTION hocalist.hocatrends_winners(p_limit integer DEFAULT 10)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  v_size integer;
  v_items jsonb;
BEGIN
  PERFORM hocalist.discovery_assert_active_member(u);
  v_size := greatest(1, least(coalesce(p_limit, 10), 30));
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'outcome_id', s.id,
      'category_label', c.label,
      'buyer_label', hocalist.review_reviewer_label(s.buyer_user_id),
      'area_label', CASE
        WHEN coalesce(pc.is_public, false) AND pc.show_area THEN rp.area_label
        ELSE NULL END,
      'confirmed_at', s.confirmed_at,
      'verified_purchase', true)
      ORDER BY s.confirmed_at DESC, s.id DESC), '[]'::jsonb)
    INTO v_items
    FROM (
      SELECT * FROM hocalist.sale_confirmations
      ORDER BY confirmed_at DESC, id DESC LIMIT v_size
    ) s
    LEFT JOIN hocalist.requests r ON r.id = s.request_id
    LEFT JOIN hocalist.catalogue_categories c ON c.id = r.category_id
    LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = r.buyer_profile_id
    LEFT JOIN hocalist.buyer_public_profile_consent pc ON pc.user_id = s.buyer_user_id;
  RETURN jsonb_build_object(
    'window_days', 30,
    'generated_at', now(),
    'items', v_items);
END $$;

REVOKE ALL ON FUNCTION hocalist.buyer_public_profile_consent_json(),
  hocalist.buyer_public_profile_consent_set(text,jsonb),
  hocalist.buyer_public_profile(uuid),
  hocalist.hocatrends_trends(integer), hocalist.hocatrends_winners(integer)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.buyer_public_profile_consent_json(),
  hocalist.buyer_public_profile_consent_set(text,jsonb),
  hocalist.buyer_public_profile(uuid),
  hocalist.hocatrends_trends(integer), hocalist.hocatrends_winners(integer)
  TO authenticated;
COMMIT;


-- ===========================================================================
-- 144_discovery_enquiry.sql
-- ===========================================================================
-- Additive Store and Hocatrends enquiry opener with origin isolation.
--
-- Buyers may open a discovery conversation from a published Store listing or
-- from a verified Hocatrends topic. The server resolves the counterpart,
-- verifies that the subject is publicly visible and that the seller currently
-- has a matching active membership, and only then delegates to the reviewed
-- `chat_open_internal` boundary. No targeting fee or buyer reward applies to
-- these origins, and no generic participant list can be supplied by a client.
--
-- Prerequisites: chat/010 (chat_open_internal), marketplace/020, and
-- discovery_completion/140 for the seller-profile helper.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

DO $guard$ BEGIN
  IF to_regprocedure('hocalist.chat_open_internal(text,uuid,uuid,uuid,uuid,jsonb)') IS NULL
     OR to_regclass('hocalist.store_listings') IS NULL
     OR to_regclass('hocalist.catalogue_categories') IS NULL THEN
    RAISE EXCEPTION 'chat 010 / marketplace 020 prerequisite missing';
  END IF;
  IF to_regprocedure('hocalist.discovery_open_enquiry(text,jsonb)') IS NOT NULL THEN
    RAISE EXCEPTION 'discovery enquiry opener already installed';
  END IF;
END; $guard$;

CREATE FUNCTION hocalist.discovery_open_enquiry(p_key text, p_input jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  v_buyer_profile uuid;
  v_origin text;
  v_listing hocalist.store_listings%ROWTYPE;
  v_topic uuid;
  v_seller_user uuid;
  v_seller_profile uuid;
  v_subject uuid;
  h text;
  receipt hocalist.marketplace_receipts%ROWTYPE;
  v_conversation uuid;
  v_participants jsonb;
BEGIN
  IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  SELECT id INTO v_buyer_profile FROM hocalist.memberships
    WHERE user_id = u AND role = 'buyer' AND status = 'active' LIMIT 1;
  IF v_buyer_profile IS NULL THEN
    RAISE EXCEPTION 'buyer_membership_required' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = u AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  IF p_key IS NULL OR length(btrim(p_key)) NOT BETWEEN 1 AND 128
     OR p_input IS NULL OR jsonb_typeof(p_input) <> 'object' THEN
    RAISE EXCEPTION 'invalid_enquiry' USING ERRCODE='22023';
  END IF;
  v_origin := p_input->>'origin';
  IF v_origin = 'store_listing' THEN
    IF p_input - ARRAY['origin','listing_id'] <> '{}'::jsonb
       OR p_input->>'listing_id' IS NULL
       OR (p_input->>'listing_id') !~ '^[0-9a-fA-F-]{36}$' THEN
      RAISE EXCEPTION 'invalid_enquiry' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_listing FROM hocalist.store_listings
      WHERE id = (p_input->>'listing_id')::uuid
        AND status = 'active' AND moderation_status = 'approved';
    IF NOT FOUND THEN RAISE EXCEPTION 'listing_not_found' USING ERRCODE='P0002'; END IF;
    v_seller_user := v_listing.seller_user_id;
    v_seller_profile := v_listing.seller_profile_id;
    v_subject := v_listing.id;
  ELSIF v_origin = 'hocatrends_enquiry' THEN
    IF p_input - ARRAY['origin','topic_id','seller_profile_id'] <> '{}'::jsonb
       OR p_input->>'topic_id' IS NULL
       OR p_input->>'seller_profile_id' IS NULL
       OR (p_input->>'topic_id') !~ '^[0-9a-fA-F-]{36}$'
       OR (p_input->>'seller_profile_id') !~ '^[0-9a-fA-F-]{36}$' THEN
      RAISE EXCEPTION 'invalid_enquiry' USING ERRCODE='22023';
    END IF;
    v_topic := (p_input->>'topic_id')::uuid;
    IF NOT EXISTS (SELECT 1 FROM hocalist.catalogue_categories
                   WHERE id = v_topic AND status = 'active') THEN
      RAISE EXCEPTION 'topic_not_found' USING ERRCODE='P0002';
    END IF;
    SELECT m.user_id INTO v_seller_user FROM hocalist.memberships m
      WHERE m.id = (p_input->>'seller_profile_id')::uuid
        AND m.role = 'seller';
    IF NOT FOUND THEN RAISE EXCEPTION 'seller_not_found' USING ERRCODE='P0002'; END IF;
    IF EXISTS (SELECT 1 FROM hocalist.memberships m
               WHERE m.user_id = v_seller_user
                 AND m.status IN ('restricted','disabled')) THEN
      RAISE EXCEPTION 'seller_not_eligible' USING ERRCODE='P0001';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM hocalist.memberships m
                   WHERE m.user_id = v_seller_user AND m.status = 'active') THEN
      RAISE EXCEPTION 'seller_not_eligible' USING ERRCODE='P0001';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM hocalist.store_listings l
      WHERE l.seller_user_id = v_seller_user
        AND l.seller_profile_id = (p_input->>'seller_profile_id')::uuid
        AND l.category_id = v_topic
        AND l.status = 'active' AND l.moderation_status = 'approved'
    ) THEN
      RAISE EXCEPTION 'seller_not_eligible' USING ERRCODE='P0001';
    END IF;
    v_seller_profile := (p_input->>'seller_profile_id')::uuid;
    v_subject := v_topic;
  ELSE
    RAISE EXCEPTION 'invalid_origin' USING ERRCODE='22023';
  END IF;
  IF v_seller_user = u THEN
    RAISE EXCEPTION 'enquiry_self' USING ERRCODE='22023';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = v_seller_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'seller_not_eligible' USING ERRCODE='P0001';
  END IF;

  h := encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(u::text||':discovery_enquiry:'||p_key,0));
  SELECT * INTO receipt FROM hocalist.marketplace_receipts
    WHERE user_id = u AND operation = 'discovery.open_enquiry' AND idempotency_key = p_key;
  IF FOUND THEN
    IF receipt.request_hash <> h THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='P0001'; END IF;
    RETURN receipt.result;
  END IF;

  v_participants := jsonb_build_array(
    jsonb_build_object('user_id', u, 'profile_id', v_buyer_profile, 'role', 'buyer'),
    jsonb_build_object('user_id', v_seller_user, 'profile_id', v_seller_profile, 'role', 'seller'));
  v_conversation := hocalist.chat_open_internal(
    v_origin,
    NULL,
    NULL,
    CASE WHEN v_origin = 'store_listing' THEN v_listing.id ELSE NULL END,
    CASE WHEN v_origin = 'hocatrends_enquiry' THEN v_topic ELSE NULL END,
    v_participants);
  INSERT INTO hocalist.marketplace_receipts(user_id, operation, idempotency_key, request_hash, result)
  VALUES (u, 'discovery.open_enquiry', p_key, h, jsonb_build_object(
    'conversation_id', v_conversation,
    'origin', v_origin,
    'subject_id', v_subject));
  RETURN jsonb_build_object(
    'conversation_id', v_conversation,
    'origin', v_origin,
    'subject_id', v_subject);
END $$;

REVOKE ALL ON FUNCTION hocalist.discovery_open_enquiry(text,jsonb)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.discovery_open_enquiry(text,jsonb) TO authenticated;
COMMIT;


-- ===========================================================================
-- 145_seller_outcomes.sql
-- ===========================================================================
-- Additive seller outcome projection for the approved Meets completion state.
--
-- The Meets screen may only show a meeting as completed when a confirmed
-- purchase outcome exists for it. This read returns the seller's own
-- confirmed outcomes with their meeting ids; it carries no buyer contacts,
-- address or PIN material.
--
-- Prerequisites: outcomes/080 (sale_confirmations) and marketplace/020.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

DO $guard$ BEGIN
  IF to_regclass('hocalist.sale_confirmations') IS NULL
     OR to_regprocedure('hocalist.marketplace_assert_role(uuid,text)') IS NULL THEN
    RAISE EXCEPTION 'marketplace/outcomes prerequisite missing';
  END IF;
  IF to_regprocedure('hocalist.marketplace_seller_outcomes(integer)') IS NOT NULL THEN
    RAISE EXCEPTION 'seller outcomes already installed';
  END IF;
END; $guard$;

CREATE FUNCTION hocalist.marketplace_seller_outcomes(p_limit integer DEFAULT 100)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  v_size integer;
BEGIN
  PERFORM hocalist.marketplace_assert_role(u, 'seller');
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023';
  END IF;
  v_size := p_limit;
  RETURN jsonb_build_object(
    'items', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'outcome_id', s.id,
        'meeting_id', s.meeting_id,
        'request_id', s.request_id,
        'offer_id', s.offer_id,
        'confirmed_at', s.confirmed_at)
        ORDER BY s.confirmed_at DESC, s.id DESC)
      FROM (SELECT * FROM hocalist.sale_confirmations
            WHERE seller_user_id = u
            ORDER BY confirmed_at DESC, id DESC LIMIT v_size) s), '[]'::jsonb));
END $$;

REVOKE ALL ON FUNCTION hocalist.marketplace_seller_outcomes(integer)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.marketplace_seller_outcomes(integer) TO authenticated;
COMMIT;


-- ===========================================================================
-- 146_topic_sellers.sql
-- ===========================================================================
-- Additive Hocatrends topic seller results.
--
-- Returns the sellers who currently have a published listing in a topic
-- (active catalogue category), with their public reputation aggregate. Used by
-- the signed-in Hocatrends seller results and by the enquiry opener, which
-- re-validates eligibility server-side. No coordinates, contacts or private
-- offers are projected.
--
-- Prerequisites: marketplace/020 + discovery_completion/142 (reviews).
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

DO $guard$ BEGIN
  IF to_regclass('hocalist.store_listings') IS NULL
     OR to_regclass('hocalist.catalogue_categories') IS NULL
     OR to_regprocedure('hocalist.seller_public_reputation(uuid)') IS NULL
     OR to_regprocedure('hocalist.discovery_assert_active_member(uuid)') IS NULL THEN
    RAISE EXCEPTION 'marketplace/reviews/140 prerequisite missing';
  END IF;
  IF to_regprocedure('hocalist.hocatrends_topic_sellers(uuid,integer)') IS NOT NULL THEN
    RAISE EXCEPTION 'Hocatrends topic sellers already installed';
  END IF;
END; $guard$;

CREATE FUNCTION hocalist.hocatrends_topic_sellers(
  p_topic uuid,
  p_limit integer DEFAULT 20
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  u uuid := auth.uid();
  v_size integer;
BEGIN
  PERFORM hocalist.discovery_assert_active_member(u);
  IF p_topic IS NULL THEN RAISE EXCEPTION 'invalid_topic' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM hocalist.catalogue_categories
                 WHERE id = p_topic AND status = 'active') THEN
    RAISE EXCEPTION 'topic_not_found' USING ERRCODE='P0002';
  END IF;
  v_size := greatest(1, least(coalesce(p_limit, 20), 50));
  RETURN jsonb_build_object(
    'topic_id', p_topic,
    'items', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'seller_profile_id', t.seller_profile_id,
        'seller_user_id', t.seller_user_id,
        'display_name', t.display_name,
        'area_label', t.area_label,
        'listing_id', t.listing_id,
        'listing_title', t.listing_title,
        'price_label', t.price_label,
        'rating_sum', t.rating_sum,
        'rating_count', t.rating_count,
        'completed_deals', t.completed_deals)
        ORDER BY t.rating_count DESC, t.rating_sum DESC,
                 t.confirmed_deals DESC, t.listing_title)
      FROM (
        SELECT
          l.seller_profile_id,
          l.seller_user_id,
          coalesce(nullif(btrim(rp.display_name), ''), 'Hocalist seller') AS display_name,
          rp.area_label,
          l.id AS listing_id,
          l.title AS listing_title,
          l.price_label AS price_label,
          coalesce(rep.rating_sum, 0) AS rating_sum,
          coalesce(rep.rating_count, 0) AS rating_count,
          coalesce((SELECT count(*)::integer FROM hocalist.sale_confirmations s
                    WHERE s.seller_user_id = l.seller_user_id), 0) AS completed_deals,
          (SELECT count(*) FROM hocalist.sale_confirmations s
           WHERE s.seller_user_id = l.seller_user_id) AS confirmed_deals
        FROM hocalist.store_listings l
        LEFT JOIN hocalist.role_profiles rp ON rp.membership_id = l.seller_profile_id
        LEFT JOIN LATERAL (
          SELECT sum(r.rating)::integer AS rating_sum,
                 count(*)::integer AS rating_count
          FROM hocalist.outcome_reviews r
          WHERE r.seller_profile_id = l.seller_profile_id
            AND r.status = 'published'
        ) rep ON true
        WHERE l.category_id = p_topic
          AND l.status = 'active'
          AND l.moderation_status = 'approved'
          AND NOT EXISTS (
            SELECT 1 FROM hocalist.memberships m3
            WHERE m3.user_id = l.seller_user_id
              AND m3.status IN ('restricted','disabled'))
        ORDER BY l.created_at DESC, l.id DESC
        LIMIT v_size
      ) t), '[]'::jsonb));
END $$;

REVOKE ALL ON FUNCTION hocalist.hocatrends_topic_sellers(uuid,integer)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.hocatrends_topic_sellers(uuid,integer)
  TO authenticated;
COMMIT;



-- ===========================================================================
-- Post-apply verification (same blocks as rollout/verify.sql)
-- ===========================================================================
-- Shared post-apply verification body. Included verbatim in apply.sql and used
-- standalone by verify.sql. Read-only checks.
DO $hocalist_discovery_completion_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_table text;
  v_role text;
  v_priv text;
  v_fn text;
  v_roles constant text[] := ARRAY['anon','authenticated','service_role'];
  v_privileges constant text[] := ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'];
  v_tables constant text[] := ARRAY[
    'seller_discovery_origins','outcome_reviews','buyer_public_profile_consent'];
  v_client_functions constant text[] := ARRAY[
    'discovery_origin_json()','discovery_origin_set(text,jsonb)',
    'marketplace_discovery_leads(text,uuid,text,integer,text,text,integer,text,bigint,bigint)',
    'marketplace_recommended_leads(integer)',
    'review_status(uuid)','review_submit(text,jsonb)','review_update(text,jsonb)',
    'seller_public_reputation(uuid)',
    'buyer_public_profile_consent_json()','buyer_public_profile_consent_set(text,jsonb)',
    'buyer_public_profile(uuid)','hocatrends_trends(integer)','hocatrends_winners(integer)',
    'discovery_open_enquiry(text,jsonb)','marketplace_seller_outcomes(integer)',
    'hocatrends_topic_sellers(uuid,integer)'];
  v_internal_functions constant text[] := ARRAY[
    'discovery_distance_miles(double precision,double precision,double precision,double precision)',
    'discovery_declared_category_ids(uuid)',
    'discovery_assert_active_member(uuid)',
    'discovery_lead_json(uuid,double precision,integer,jsonb)',
    'review_reviewer_label(uuid)','review_json(uuid)'];
BEGIN
  FOREACH v_table IN ARRAY v_tables LOOP
    IF to_regclass('hocalist.' || v_table) IS NULL THEN
      v_issues := array_append(v_issues, 'missing discovery_completion table: ' || v_table);
    ELSIF NOT (SELECT relrowsecurity FROM pg_class WHERE oid=('hocalist.' || v_table)::regclass) THEN
      v_issues := array_append(v_issues, 'row level security disabled: ' || v_table);
    END IF;
    FOREACH v_role IN ARRAY v_roles LOOP
      FOREACH v_priv IN ARRAY v_privileges LOOP
        IF has_table_privilege(v_role, 'hocalist.' || v_table, v_priv) THEN
          v_issues := array_append(v_issues,
            'unexpected ' || v_priv || ' for ' || v_role || ' on ' || v_table);
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
  FOREACH v_fn IN ARRAY v_client_functions LOOP
    IF NOT has_function_privilege('authenticated', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('anon', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('service_role', 'hocalist.' || v_fn, 'EXECUTE') THEN
      v_issues := array_append(v_issues, 'discovery_completion function grants are wrong: ' || v_fn);
    END IF;
  END LOOP;
  -- review_moderate is admin-only through marketplace_assert_admin but is
  -- granted to authenticated so the reviewed admin RPC path can reach it.
  IF NOT has_function_privilege('authenticated','hocalist.review_moderate(text,jsonb)','EXECUTE')
     OR has_function_privilege('anon','hocalist.review_moderate(text,jsonb)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'review_moderate grant is wrong');
  END IF;
  FOREACH v_fn IN ARRAY v_internal_functions LOOP
    IF has_function_privilege('authenticated', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('anon', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('service_role', 'hocalist.' || v_fn, 'EXECUTE') THEN
      v_issues := array_append(v_issues, 'internal discovery_completion function is executable: ' || v_fn);
    END IF;
  END LOOP;
  -- Deployed chat and marketplace state must be untouched.
  IF NOT has_function_privilege('authenticated','hocalist.chat_send(uuid,text,text)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.marketplace_command(text,text,jsonb)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.sale_pin(uuid,text,text)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'deployed chat/marketplace/outcome grants changed');
  END IF;
  IF coalesce(array_length(v_issues,1),0) > 0 THEN
    RAISE EXCEPTION 'hocalist discovery_completion post-apply verification failed: %', array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_discovery_completion_postapply$;

-- Post-apply drift verification: pinned prerequisite and package definition
-- hashes, authorization signature inventory, and the exact new table/column
-- inventory with RLS and no unexpected policies.
DO $hocalist_discovery_completion_hashes$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_pair text;
  v_signature text;
  v_hash text;
  v_table text;
  v_expected_columns text[];
  v_actual_columns text[];
  v_expected_prerequisites constant text[] := ARRAY[
      'marketplace_assert_role(uuid,text)=dd119186e84a565ff963563e30147bc0',
  'marketplace_assert_admin(uuid)=938e63c0f29b421238433c4126b09969',
  'marketplace_is_admin(uuid)=74bd28a1f59ed68a760cde8955d50e78',
  'chat_open_internal(text,uuid,uuid,uuid,uuid,jsonb)=e9e39a2fb889dd31fcf4c9581e267be5'
  ];
  v_expected_package constant text[] := ARRAY[
      'discovery_distance_miles(double precision,double precision,double precision,double precision)=57f326243368d1300600bbb271a4bd16',
  'discovery_declared_category_ids(uuid)=25e47009ea711f8358cd98760207fc62',
  'discovery_assert_active_member(uuid)=7279a66ce102222922637a711a0c0f03',
  'discovery_origin_json()=db69ed263414dc3cd1f11b79c2ef6cdc',
  'discovery_origin_set(text,jsonb)=48eade4966a4755d6890a19148859d9c',
  'discovery_lead_json(uuid,double precision,integer,jsonb)=5f6e35abb8033228ac01f13bff3abb77',
  'marketplace_discovery_leads(text,uuid,text,integer,text,text,integer,text,bigint,bigint)=be33038e027379ba9ba64686b0f995ef',
  'marketplace_recommended_leads(integer)=aa00ae988071499a8d5b6b716f0633d4',
  'review_reviewer_label(uuid)=871e15b82603fd305f9cc51c8a8b59e0',
  'review_json(uuid)=00c2db03ca13ccc753dde30e78f9ed5f',
  'review_status(uuid)=077de59713d529326725a1c5661dd703',
  'review_submit(text,jsonb)=acf5e3fb8372b39d1dbffc34217b6dc0',
  'review_update(text,jsonb)=f10bfcae505426a14322f61ac2dd0f32',
  'review_moderate(text,jsonb)=7e896fe59d5f190dc8c7c6cb7ef760de',
  'seller_public_reputation(uuid)=cd77ff375f77be2255fe4ec26f0bf132',
  'buyer_public_profile_consent_json()=ec171cce7aed7790ea2d11c923e3987b',
  'buyer_public_profile_consent_set(text,jsonb)=d73f3e3fe48e8f7934088c1f04b8ae7f',
  'buyer_public_profile(uuid)=fffb93fe900a5384f767f0de5b9bd5eb',
  'hocatrends_trends(integer)=d389c30885da159d8e0ee3c4463643ee',
  'hocatrends_winners(integer)=55fc0f9f4270fa05743ca46c6c3e176b',
  'discovery_open_enquiry(text,jsonb)=bbbcaf2a16d187f916563fc3c2bf89a3',
  'marketplace_seller_outcomes(integer)=411d281aa86b53829d8d3e040da2ef14',
  'hocatrends_topic_sellers(uuid,integer)=a45cc02d3b9402329ecb4fa9c9cd9999'
  ];
  v_tables constant text[] := ARRAY[
    'seller_discovery_origins','outcome_reviews','buyer_public_profile_consent'];
BEGIN
  FOREACH v_pair IN ARRAY v_expected_prerequisites LOOP
    v_signature := split_part(v_pair, '=', 1);
    v_hash := split_part(v_pair, '=', 2);
    IF to_regprocedure('hocalist.' || v_signature) IS NULL THEN
      v_issues := array_append(v_issues, 'prerequisite function missing: ' || v_signature);
    ELSIF (SELECT md5(replace(prosrc, chr(13), '')) FROM pg_proc
           WHERE oid = ('hocalist.' || v_signature)::regprocedure) IS DISTINCT FROM v_hash THEN
      v_issues := array_append(v_issues, 'prerequisite definition drift: ' || v_signature);
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'hocalist'
        AND p.proname IN ('marketplace_assert_role','marketplace_is_admin',
                          'marketplace_assert_admin','chat_open_internal',
                          'discovery_assert_active_member')) <> 5 THEN
    v_issues := array_append(v_issues, 'authorization function overload inventory changed');
  END IF;
  FOREACH v_pair IN ARRAY v_expected_package LOOP
    v_signature := split_part(v_pair, '=', 1);
    v_hash := split_part(v_pair, '=', 2);
    IF to_regprocedure('hocalist.' || v_signature) IS NULL THEN
      v_issues := array_append(v_issues, 'package function missing: ' || v_signature);
    ELSIF (SELECT md5(replace(prosrc, chr(13), '')) FROM pg_proc
           WHERE oid = ('hocalist.' || v_signature)::regprocedure) IS DISTINCT FROM v_hash THEN
      v_issues := array_append(v_issues, 'package definition drift: ' || v_signature);
    END IF;
  END LOOP;
  FOREACH v_table IN ARRAY v_tables LOOP
    IF to_regclass('hocalist.' || v_table) IS NULL THEN
      v_issues := array_append(v_issues, 'missing package table: ' || v_table);
      CONTINUE;
    END IF;
    v_expected_columns := CASE v_table
      WHEN 'seller_discovery_origins' THEN ARRAY[
        'area_label','created_at','latitude','longitude','radius_miles','revision',
        'seller_profile_id','seller_user_id','updated_at']
      WHEN 'outcome_reviews' THEN ARRAY[
        'body','buyer_user_id','created_at','id','meeting_id','moderated_at','moderated_by',
        'moderation_reason','offer_id','rating','request_id','revision','seller_profile_id',
        'seller_user_id','status','updated_at']
      ELSE ARRAY[
        'created_at','is_public','revision','show_area','show_categories',
        'show_display_name','updated_at','user_id']
    END;
    SELECT array_agg(column_name::text ORDER BY column_name) INTO v_actual_columns
      FROM information_schema.columns
      WHERE table_schema = 'hocalist' AND table_name = v_table;
    IF v_actual_columns IS DISTINCT FROM v_expected_columns THEN
      v_issues := array_append(v_issues, 'package table columns changed: ' || v_table);
    END IF;
    IF NOT (SELECT relrowsecurity FROM pg_class
            WHERE oid = ('hocalist.' || v_table)::regclass) THEN
      v_issues := array_append(v_issues, 'package table RLS disabled: ' || v_table);
    END IF;
    IF EXISTS (SELECT 1 FROM pg_policies
               WHERE schemaname = 'hocalist' AND tablename = v_table) THEN
      v_issues := array_append(v_issues, 'unexpected package table policy: ' || v_table);
    END IF;
  END LOOP;
  IF coalesce(array_length(v_issues,1),0) > 0 THEN
    RAISE EXCEPTION 'hocalist discovery_completion drift verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_discovery_completion_hashes$;
